-- Migration crm-003: AA-934 (partner CRM, design v3 card CRM-06) — the identity vault: the per-tenant data-key store,
-- the encrypted integration credentials, the traveller vault columns and the append-only audit of denials.
--
-- Owner: AA-Partner (api/migrations/003_crm_vault_keys.sql). AA-CIS-Infra db/migrations/crm/ holds the byte copy
-- DB Migrate applies (Migration Copy Guard). Key crm-003.
--
-- Why. Design v3 §4.1 / lane §5.1: one data key (DEK) per agency per purpose, generated by KMS (alias/crm-<env>/data,
-- AA-932) under the encryption context {tenant_id, purpose} and stored only wrapped; personal fields are AES-256-GCM
-- ciphertext bound to tenant, table, column and row; exact search and dedupe go through blind indexes (HKDF of the
-- tenant's vault DEK, lane §5.2). The card's R test needs a place to record a refused decrypt ("audited denied").
--
-- What:
--   1. crm.reject_append_only_change(): trigger function for append-only tables (UPDATE / DELETE / TRUNCATE refused).
--   2. crm.tenant_key: the DEK store on Dev (design §3.1 "DEK store: crm.tenant_key on Dev"). One row per
--      (tenant, purpose, key_version); wrapped_dek is the KEK-wrapped DEK, never plaintext; kek_provider / kek_id name
--      the KEK it is wrapped under (rewrap = BYOK path). At most one current (not retired) key per (tenant, purpose).
--      A guard trigger keeps identity columns fixed, makes retire / destroy one-way and allows DELETE only of a
--      destroyed row (offboarding, CRM-35).
--   3. crm.integration_credential: the agency's own vendor credentials (errata S247, ADR 0010 decision 9):
--      provider list twilio / stripe_key / stripe_webhook_secret / google / microsoft / smtp / esign, secret_enc under
--      the tenant's integration DEK, the Connections wizard health columns and the four states with their moves.
--   4. crm.traveler: the F1 identity vault row (lane §2.3): every identity, contact and document field encrypted
--      (*_enc), blind indexes (*_bidx) for exact search and dedupe, plain lifecycle columns. CRM-08 writes rows.
--   5. crm.audit_event: append-only agency audit (lane §2.11 columns + outcome allowed / denied). Codes and ids only,
--      never personal data. crm_app may INSERT and SELECT only. CRM-12 (AA-940) adds monthly partitions, the hourly
--      Object Lock export and the audit page; this card writes the decrypt denials into it.
--   Every tenant table follows the base template (api/db/templates/tenant_table.sql); audit_event is the
--   append-only variant (no updated_at, no trash columns), checked by tests/integration/test_crm002_tenancy.py.
--   The NOLOGIN readers get nothing on any of these tables (vault rule, design §4.3; the isolation probe expects 42501).
--
-- Runs as crm_owner (DB Migrate switch), one BEGIN … COMMIT block, no role DDL. Rollback: a forward crm- file
-- (MIG-14); before AA-934 deploys nothing reads these tables.

BEGIN;

SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '15min';

-- ── Guard 0: runs as the owner, after crm-002 ────────────────────────────────────────────────────
DO $$
BEGIN
    IF current_user <> 'crm_owner' THEN
        RAISE EXCEPTION 'crm-003: must run as crm_owner (DB Migrate live-owner switch), runs as %', current_user;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM shared.schema_versions WHERE version = 'crm-002') THEN
        RAISE EXCEPTION 'crm-003: crm-002 is not registered';
    END IF;
    IF to_regclass('crm.tenant') IS NULL OR to_regclass('crm.member') IS NULL THEN
        RAISE EXCEPTION 'crm-003: crm.tenant / crm.member are missing (crm-002)';
    END IF;
END $$;

-- ── 1. Append-only trigger function ──────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION crm.reject_append_only_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = pg_catalog
AS $$
BEGIN
    RAISE EXCEPTION 'crm: % is append-only (% refused)', TG_TABLE_NAME, TG_OP
        USING ERRCODE = 'insufficient_privilege';
END;
$$;
REVOKE ALL ON FUNCTION crm.reject_append_only_change() FROM PUBLIC;

-- ── 2. crm.tenant_key ────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS crm.tenant_key (
    tenant_key_id      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id          UUID NOT NULL DEFAULT NULLIF(current_setting('app.tenant_id', true), '')::uuid
                       REFERENCES crm.tenant (tenant_id),
    purpose            TEXT NOT NULL,
    key_version        INTEGER NOT NULL,
    kek_provider       TEXT NOT NULL,
    kek_id             TEXT NOT NULL,
    wrapped_dek        BYTEA,
    encryption_context JSONB NOT NULL,
    rewrapped_at       TIMESTAMPTZ,
    retired_at         TIMESTAMPTZ,
    destroyed_at       TIMESTAMPTZ,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by         TEXT NOT NULL DEFAULT COALESCE(NULLIF(current_setting('app.actor', true), ''), current_user::text),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at         TIMESTAMPTZ,
    deleted_by         TEXT,
    purge_after        TIMESTAMPTZ,
    CONSTRAINT tenant_key_version_uq UNIQUE (tenant_id, purpose, key_version),
    CONSTRAINT tenant_key_purpose_chk CHECK (
        purpose IN ('vault', 'docs', 'integration', 'scrub', 'ops_release', 'export', 'mail')
    ),
    -- The ciphertext header holds the version in 2 bytes.
    CONSTRAINT tenant_key_version_chk CHECK (key_version BETWEEN 1 AND 65535),
    CONSTRAINT tenant_key_kek_provider_chk CHECK (kek_provider IN ('kms', 'local')),
    CONSTRAINT tenant_key_kek_id_chk CHECK (length(kek_id) BETWEEN 1 AND 2048),
    CONSTRAINT tenant_key_wrapped_chk CHECK (wrapped_dek IS NULL OR octet_length(wrapped_dek) BETWEEN 32 AND 4096),
    -- Exactly the KMS encryption context the key policy allows (AA-932): {tenant_id, purpose} of this row.
    CONSTRAINT tenant_key_context_chk CHECK (
        encryption_context = jsonb_build_object('tenant_id', tenant_id::text, 'purpose', purpose)
    ),
    -- Destroyed = crypto-shredded: the wrapped DEK is gone and the key was retired first.
    CONSTRAINT tenant_key_destroyed_chk CHECK (
        (destroyed_at IS NULL) = (wrapped_dek IS NOT NULL) AND (destroyed_at IS NULL OR retired_at IS NOT NULL)
    ),
    CONSTRAINT tenant_key_trash_chk CHECK (
        (deleted_at IS NULL) = (deleted_by IS NULL) AND (deleted_at IS NULL) = (purge_after IS NULL)
    )
);

-- One current key per tenant and purpose; new values are encrypted under it.
CREATE UNIQUE INDEX IF NOT EXISTS tenant_key_current_uq ON crm.tenant_key (tenant_id, purpose) WHERE retired_at IS NULL;

ALTER TABLE crm.tenant_key ENABLE ROW LEVEL SECURITY;
ALTER TABLE crm.tenant_key FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON crm.tenant_key;
CREATE POLICY tenant_isolation ON crm.tenant_key
    TO crm_owner, crm_app, crm_ai_reader, crm_insights, crm_support_reader, crm_eraser
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);

CREATE OR REPLACE TRIGGER tenant_key_set_updated_at
    BEFORE UPDATE ON crm.tenant_key
    FOR EACH ROW EXECUTE FUNCTION crm.set_updated_at();

CREATE OR REPLACE FUNCTION crm.tenant_key_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = pg_catalog
AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.destroyed_at IS NULL THEN
            RAISE EXCEPTION 'crm.tenant_key: a live key cannot be deleted (destroy it first)'
                USING ERRCODE = 'insufficient_privilege';
        END IF;
        RETURN OLD;
    END IF;
    IF NEW.tenant_key_id IS DISTINCT FROM OLD.tenant_key_id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.purpose IS DISTINCT FROM OLD.purpose OR NEW.key_version IS DISTINCT FROM OLD.key_version
       OR NEW.encryption_context IS DISTINCT FROM OLD.encryption_context
       OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN
        RAISE EXCEPTION 'crm.tenant_key: identity columns are fixed' USING ERRCODE = 'check_violation';
    END IF;
    IF (OLD.retired_at IS NOT NULL AND NEW.retired_at IS DISTINCT FROM OLD.retired_at)
       OR (OLD.destroyed_at IS NOT NULL AND NEW.destroyed_at IS DISTINCT FROM OLD.destroyed_at) THEN
        RAISE EXCEPTION 'crm.tenant_key: retire and destroy are one-way' USING ERRCODE = 'check_violation';
    END IF;
    -- The wrapped DEK changes only by a rewrap (rewrapped_at moves) or a destroy (it becomes NULL).
    IF NEW.wrapped_dek IS DISTINCT FROM OLD.wrapped_dek AND NEW.wrapped_dek IS NOT NULL
       AND NEW.rewrapped_at IS NOT DISTINCT FROM OLD.rewrapped_at THEN
        RAISE EXCEPTION 'crm.tenant_key: wrapped_dek changes only with rewrapped_at' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION crm.tenant_key_guard() FROM PUBLIC;

CREATE OR REPLACE TRIGGER tenant_key_guard
    BEFORE UPDATE OR DELETE ON crm.tenant_key
    FOR EACH ROW EXECUTE FUNCTION crm.tenant_key_guard();
REVOKE TRUNCATE ON crm.tenant_key FROM crm_app;

COMMENT ON TABLE crm.tenant_key IS 'AA-934 (crm-003): the DEK store on Dev (design v3 §3.1, §4.1): one data key per agency per purpose and version, wrapped under a KEK (KMS alias/crm-<env>/data, context {tenant_id, purpose}); never plaintext at rest. Base template, FORCE RLS on app.tenant_id; no reader role has any privilege.';
COMMENT ON COLUMN crm.tenant_key.wrapped_dek IS 'conf:credential; the KEK-wrapped DEK (KMS CiphertextBlob or the local AES-GCM wrap); NULL once destroyed';
COMMENT ON COLUMN crm.tenant_key.kek_id IS 'the KEK the DEK is wrapped under: the KMS key ARN KMS returned, or a local keyring id (tests / local runs)';
COMMENT ON COLUMN crm.tenant_key.encryption_context IS 'exactly {tenant_id, purpose} of the row (CHECK): the KMS encryption context of the wrap';
COMMENT ON COLUMN crm.tenant_key.key_version IS '1-65535, written into every ciphertext header; a rotation retires the current version and adds the next';

-- ── 3. crm.integration_credential ────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS crm.integration_credential (
    integration_credential_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id        UUID NOT NULL DEFAULT NULLIF(current_setting('app.tenant_id', true), '')::uuid
                     REFERENCES crm.tenant (tenant_id),
    provider         TEXT NOT NULL,
    account_ref      TEXT,
    secret_enc       BYTEA NOT NULL,
    status           TEXT NOT NULL DEFAULT 'not_set_up',
    failure_class    TEXT,
    last_checked_at  TIMESTAMPTZ,
    last_ok_at       TIMESTAMPTZ,
    last_test_at     TIMESTAMPTZ,
    last_test_result TEXT,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by       TEXT NOT NULL DEFAULT COALESCE(NULLIF(current_setting('app.actor', true), ''), current_user::text),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at       TIMESTAMPTZ,
    deleted_by       TEXT,
    purge_after      TIMESTAMPTZ,
    CONSTRAINT integration_credential_provider_uq UNIQUE (tenant_id, provider),
    CONSTRAINT integration_credential_provider_chk CHECK (
        provider IN ('twilio', 'stripe_key', 'stripe_webhook_secret', 'google', 'microsoft', 'smtp', 'esign')
    ),
    CONSTRAINT integration_credential_account_ref_chk CHECK (account_ref IS NULL OR length(account_ref) BETWEEN 1 AND 320),
    CONSTRAINT integration_credential_secret_chk CHECK (octet_length(secret_enc) BETWEEN 30 AND 16384),
    CONSTRAINT integration_credential_status_chk CHECK (
        status IN ('not_set_up', 'connected', 'needs_attention', 'disconnected')
    ),
    CONSTRAINT integration_credential_failure_chk CHECK (
        failure_class IS NULL OR failure_class IN
            ('auth_revoked', 'permission_missing', 'vendor_rejected', 'rate_limited', 'unreachable')
    ),
    CONSTRAINT integration_credential_failure_state_chk CHECK (
        failure_class IS NULL OR status IN ('needs_attention', 'disconnected')
    ),
    CONSTRAINT integration_credential_test_result_chk CHECK (
        last_test_result IS NULL OR last_test_result IN ('ok', 'failed')
    ),
    CONSTRAINT integration_credential_trash_chk CHECK (
        (deleted_at IS NULL) = (deleted_by IS NULL) AND (deleted_at IS NULL) = (purge_after IS NULL)
    )
);

ALTER TABLE crm.integration_credential ENABLE ROW LEVEL SECURITY;
ALTER TABLE crm.integration_credential FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON crm.integration_credential;
CREATE POLICY tenant_isolation ON crm.integration_credential
    TO crm_owner, crm_app, crm_ai_reader, crm_insights, crm_support_reader, crm_eraser
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);

CREATE OR REPLACE TRIGGER integration_credential_set_updated_at
    BEFORE UPDATE ON crm.integration_credential
    FOR EACH ROW EXECUTE FUNCTION crm.set_updated_at();

INSERT INTO crm.status_transition (table_name, from_status, to_status) VALUES
    ('integration_credential', 'not_set_up', 'connected'),
    ('integration_credential', 'not_set_up', 'needs_attention'),
    ('integration_credential', 'not_set_up', 'disconnected'),
    ('integration_credential', 'connected', 'needs_attention'),
    ('integration_credential', 'connected', 'disconnected'),
    ('integration_credential', 'needs_attention', 'connected'),
    ('integration_credential', 'needs_attention', 'disconnected'),
    ('integration_credential', 'disconnected', 'connected')
ON CONFLICT DO NOTHING;
CREATE OR REPLACE TRIGGER integration_credential_status_transition
    BEFORE UPDATE OF status ON crm.integration_credential
    FOR EACH ROW EXECUTE FUNCTION crm.enforce_status_transition();

COMMENT ON TABLE crm.integration_credential IS 'AA-934 (crm-003): an agency''s own vendor credential (errata S247, ADR 0010 decision 9), one per provider. secret_enc is decrypted only in the dispatcher, webhook and health-check paths (AA-Partner lint); no route returns it. Disconnect deletes the row. Base template, FORCE RLS on app.tenant_id.';
COMMENT ON COLUMN crm.integration_credential.secret_enc IS 'conf:credential; AES-256-GCM under the tenant integration DEK (key_version ‖ nonce ‖ ciphertext ‖ tag)';
COMMENT ON COLUMN crm.integration_credential.account_ref IS 'pii:contact; the vendor account reference (Twilio account SID, Stripe account id, mailbox address); never shown to AA support';
COMMENT ON COLUMN crm.integration_credential.failure_class IS 'why the connection needs attention or is disconnected (wizard health, errata S247 §2)';

-- ── 4. crm.traveler (F1 identity vault) ──────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS crm.traveler (
    traveler_id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id              UUID NOT NULL DEFAULT NULLIF(current_setting('app.tenant_id', true), '')::uuid
                           REFERENCES crm.tenant (tenant_id),
    given_name_enc         BYTEA,
    family_name_enc        BYTEA,
    display_name_enc       BYTEA NOT NULL,
    email_enc              BYTEA,
    phone_enc              BYTEA,
    preferred_channel      TEXT,
    email_bidx             BYTEA,
    phone_bidx             BYTEA,
    name_bidx              BYTEA,
    name_token_bidx        BYTEA[] NOT NULL DEFAULT '{}',
    dob_enc                BYTEA,
    nationality_enc        BYTEA,
    passport_no_enc        BYTEA,
    passport_expiry_enc    BYTEA,
    passport_country_enc   BYTEA,
    emergency_contact_enc  BYTEA,
    profile_token_enc      BYTEA,
    owner_member_id        UUID REFERENCES crm.member (member_id),
    lead_source            TEXT,
    referrer_traveler_id   UUID REFERENCES crm.traveler (traveler_id),
    archived_at            TIMESTAMPTZ,
    archive_reason         TEXT,
    created_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by             TEXT NOT NULL DEFAULT COALESCE(NULLIF(current_setting('app.actor', true), ''), current_user::text),
    updated_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at             TIMESTAMPTZ,
    deleted_by             TEXT,
    purge_after            TIMESTAMPTZ,
    -- Every *_enc value has at least the header, the nonce and the tag (2 + 12 + 16 bytes).
    CONSTRAINT traveler_enc_chk CHECK (
        octet_length(display_name_enc) >= 30
        AND coalesce(octet_length(given_name_enc), 30) >= 30
        AND coalesce(octet_length(family_name_enc), 30) >= 30
        AND coalesce(octet_length(email_enc), 30) >= 30
        AND coalesce(octet_length(phone_enc), 30) >= 30
        AND coalesce(octet_length(dob_enc), 30) >= 30
        AND coalesce(octet_length(nationality_enc), 30) >= 30
        AND coalesce(octet_length(passport_no_enc), 30) >= 30
        AND coalesce(octet_length(passport_expiry_enc), 30) >= 30
        AND coalesce(octet_length(passport_country_enc), 30) >= 30
        AND coalesce(octet_length(emergency_contact_enc), 30) >= 30
        AND coalesce(octet_length(profile_token_enc), 30) >= 30
    ),
    -- Blind index sizes (lane §5.2): email / phone 16 bytes, full name 8, name tokens 4.
    CONSTRAINT traveler_bidx_chk CHECK (
        coalesce(octet_length(email_bidx), 16) = 16
        AND coalesce(octet_length(phone_bidx), 16) = 16
        AND coalesce(octet_length(name_bidx), 8) = 8
        AND array_position(name_token_bidx, NULL) IS NULL
        AND coalesce(cardinality(name_token_bidx), 0) <= 16
    ),
    -- An index only with its value: no index can outlive or precede the encrypted field.
    CONSTRAINT traveler_bidx_pairs_chk CHECK (
        (email_bidx IS NULL) = (email_enc IS NULL) AND (phone_bidx IS NULL) = (phone_enc IS NULL)
    ),
    CONSTRAINT traveler_channel_chk CHECK (
        preferred_channel IS NULL OR preferred_channel IN ('email', 'phone', 'sms', 'whatsapp')
    ),
    CONSTRAINT traveler_lead_source_chk CHECK (lead_source IS NULL OR lead_source ~ '^[a-z][a-z0-9_]{0,39}$'),
    CONSTRAINT traveler_archive_chk CHECK (
        (archive_reason IS NULL OR archived_at IS NOT NULL)
        AND (archive_reason IS NULL OR archive_reason ~ '^[a-z][a-z0-9_]{0,39}$')
    ),
    CONSTRAINT traveler_referrer_chk CHECK (referrer_traveler_id IS DISTINCT FROM traveler_id),
    CONSTRAINT traveler_trash_chk CHECK (
        (deleted_at IS NULL) = (deleted_by IS NULL) AND (deleted_at IS NULL) = (purge_after IS NULL)
    )
);

-- Exact search and dedupe (R6, R35) and inbound matching by phone (CRM-28), per agency.
CREATE INDEX IF NOT EXISTS traveler_email_bidx_idx ON crm.traveler (tenant_id, email_bidx)
    WHERE email_bidx IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS traveler_phone_bidx_idx ON crm.traveler (tenant_id, phone_bidx)
    WHERE phone_bidx IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS traveler_name_bidx_idx ON crm.traveler (tenant_id, name_bidx)
    WHERE name_bidx IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS traveler_name_token_bidx_idx ON crm.traveler USING gin (name_token_bidx);
CREATE INDEX IF NOT EXISTS traveler_owner_member_idx ON crm.traveler (owner_member_id) WHERE owner_member_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS traveler_referrer_idx ON crm.traveler (referrer_traveler_id)
    WHERE referrer_traveler_id IS NOT NULL;

ALTER TABLE crm.traveler ENABLE ROW LEVEL SECURITY;
ALTER TABLE crm.traveler FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON crm.traveler;
CREATE POLICY tenant_isolation ON crm.traveler
    TO crm_owner, crm_app, crm_ai_reader, crm_insights, crm_support_reader, crm_eraser
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);

CREATE OR REPLACE TRIGGER traveler_set_updated_at
    BEFORE UPDATE ON crm.traveler
    FOR EACH ROW EXECUTE FUNCTION crm.set_updated_at();

COMMENT ON TABLE crm.traveler IS 'AA-934 (crm-003): the agency''s traveller, F1 identity vault (design v3 §3.3 group B, lane §2.3). Every identity, contact and document value is AES-256-GCM ciphertext (*_enc, AAD = tenant, table, column, row id) under the tenant vault DEK; *_bidx are blind indexes (truncated HMAC, HKDF of the vault DEK). Base template, FORCE RLS; no reader role has any privilege (design §4.3).';
COMMENT ON COLUMN crm.traveler.given_name_enc IS 'pii:name; encrypted (vault DEK), as on the passport';
COMMENT ON COLUMN crm.traveler.family_name_enc IS 'pii:name; encrypted (vault DEK), as on the passport';
COMMENT ON COLUMN crm.traveler.display_name_enc IS 'pii:name; encrypted (vault DEK); the only field list views decrypt (design §4.4)';
COMMENT ON COLUMN crm.traveler.email_enc IS 'pii:contact; encrypted (vault DEK)';
COMMENT ON COLUMN crm.traveler.phone_enc IS 'pii:contact; encrypted (vault DEK), E.164';
COMMENT ON COLUMN crm.traveler.email_bidx IS 'pii:contact; blind index of the normalised email (16-byte truncated HMAC, per-tenant key)';
COMMENT ON COLUMN crm.traveler.phone_bidx IS 'pii:contact; blind index of the E.164 phone (16-byte truncated HMAC, per-tenant key)';
COMMENT ON COLUMN crm.traveler.name_bidx IS 'pii:name; blind index of the normalised full name (8 bytes, deliberately lossy)';
COMMENT ON COLUMN crm.traveler.name_token_bidx IS 'pii:name; one 4-byte blind index per name token (deliberately lossy; candidates are confirmed after decrypting)';
COMMENT ON COLUMN crm.traveler.dob_enc IS 'pii:government_id; encrypted (vault DEK), ISO date';
COMMENT ON COLUMN crm.traveler.nationality_enc IS 'pii:government_id; encrypted (vault DEK)';
COMMENT ON COLUMN crm.traveler.passport_no_enc IS 'pii:government_id; encrypted (vault DEK)';
COMMENT ON COLUMN crm.traveler.passport_expiry_enc IS 'pii:government_id; encrypted (vault DEK)';
COMMENT ON COLUMN crm.traveler.passport_country_enc IS 'pii:government_id; encrypted (vault DEK)';
COMMENT ON COLUMN crm.traveler.emergency_contact_enc IS 'pii:emergency_contact; encrypted (vault DEK)';
COMMENT ON COLUMN crm.traveler.profile_token_enc IS 'pii:profile; the encrypted pointer to the F2 profile token (design §4.3); the only F1 to F2 link';
COMMENT ON COLUMN crm.traveler.lead_source IS 'a source code (form, import, referral, ...), never free text';

-- ── 5. crm.audit_event (append-only) ─────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS crm.audit_event (
    event_id     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id    UUID NOT NULL DEFAULT NULLIF(current_setting('app.tenant_id', true), '')::uuid
                 REFERENCES crm.tenant (tenant_id),
    at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    actor_kind   TEXT NOT NULL,
    actor_ref    TEXT NOT NULL,
    action       TEXT NOT NULL,
    outcome      TEXT NOT NULL,
    object_kind  TEXT NOT NULL,
    object_id    TEXT,
    fields       TEXT[] NOT NULL DEFAULT '{}',
    reason       TEXT,
    request_id   TEXT,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by   TEXT NOT NULL DEFAULT COALESCE(NULLIF(current_setting('app.actor', true), ''), current_user::text),
    CONSTRAINT audit_event_actor_kind_chk CHECK (
        actor_kind IN ('user', 'traveler', 'ai_agent', 'aa_ops', 'aa_staff', 'support', 'breakglass', 'system')
    ),
    -- Random ids and codes only: nothing here may carry personal data (design §3.3 group J).
    CONSTRAINT audit_event_actor_ref_chk CHECK (actor_ref ~ '^[A-Za-z0-9:_-]{1,80}$'),
    CONSTRAINT audit_event_action_chk CHECK (action ~ '^[a-z][a-z0-9_]{0,39}$'),
    CONSTRAINT audit_event_outcome_chk CHECK (outcome IN ('allowed', 'denied')),
    CONSTRAINT audit_event_object_kind_chk CHECK (object_kind ~ '^[a-z][a-z0-9_]{0,39}$'),
    CONSTRAINT audit_event_object_id_chk CHECK (object_id IS NULL OR object_id ~ '^[A-Za-z0-9:_-]{1,80}$'),
    CONSTRAINT audit_event_fields_chk CHECK (
        cardinality(fields) <= 32 AND array_to_string(fields, ',', '!') ~ '^([a-z][a-z0-9_]{0,62}(,|$))*$'
    ),
    CONSTRAINT audit_event_reason_chk CHECK (reason IS NULL OR reason ~ '^[a-z][a-z0-9_]{0,63}$'),
    CONSTRAINT audit_event_request_id_chk CHECK (request_id IS NULL OR request_id ~ '^[A-Za-z0-9._:-]{1,128}$')
);

CREATE INDEX IF NOT EXISTS audit_event_tenant_at_idx ON crm.audit_event (tenant_id, at DESC);
CREATE INDEX IF NOT EXISTS audit_event_object_idx ON crm.audit_event (tenant_id, object_kind, object_id);

ALTER TABLE crm.audit_event ENABLE ROW LEVEL SECURITY;
ALTER TABLE crm.audit_event FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON crm.audit_event;
CREATE POLICY tenant_isolation ON crm.audit_event
    TO crm_owner, crm_app, crm_ai_reader, crm_insights, crm_support_reader, crm_eraser
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);

CREATE OR REPLACE TRIGGER audit_event_append_only
    BEFORE UPDATE OR DELETE ON crm.audit_event
    FOR EACH ROW EXECUTE FUNCTION crm.reject_append_only_change();
CREATE OR REPLACE TRIGGER audit_event_no_truncate
    BEFORE TRUNCATE ON crm.audit_event
    FOR EACH STATEMENT EXECUTE FUNCTION crm.reject_append_only_change();
REVOKE UPDATE, DELETE, TRUNCATE ON crm.audit_event FROM crm_app;

COMMENT ON TABLE crm.audit_event IS 'AA-934 (crm-003): the agency audit (F5), append-only: crm_app INSERT + SELECT, a trigger refuses UPDATE, DELETE and TRUNCATE. Codes and random ids only, never personal data. AA-934 writes decrypt denials (outcome denied); CRM-12 (AA-940) adds monthly partitions, the Object Lock export and the audit page. Retention: data standards §7 row crm.audit_event.';
COMMENT ON COLUMN crm.audit_event.actor_ref IS 'a random id only (member:<uuid>, system:<kind>), never a name or an e-mail';
COMMENT ON COLUMN crm.audit_event.fields IS 'column names touched (for example display_name_enc), never values';
COMMENT ON COLUMN crm.audit_event.reason IS 'a reason code (integrity_check_failed, tenant_mismatch, ...), never free text';

-- ── Guard 1: the shape this file promises ────────────────────────────────────────────────────────
DO $$
DECLARE
    t text;
    p text;
    r text;
BEGIN
    FOREACH t IN ARRAY ARRAY['crm.tenant_key', 'crm.integration_credential', 'crm.traveler', 'crm.audit_event'] LOOP
        IF NOT (SELECT relrowsecurity AND relforcerowsecurity FROM pg_catalog.pg_class WHERE oid = t::regclass) THEN
            RAISE EXCEPTION 'crm-003: % must have ENABLE + FORCE row level security', t;
        END IF;
        -- The vault rule (design §4.3): no NOLOGIN reader reaches these tables.
        FOREACH r IN ARRAY ARRAY['crm_ai_reader', 'crm_insights', 'crm_support_reader', 'crm_eraser'] LOOP
            FOREACH p IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE'] LOOP
                IF pg_catalog.has_table_privilege(r, t, p) THEN
                    RAISE EXCEPTION 'crm-003: % may % on %', r, p, t;
                END IF;
            END LOOP;
        END LOOP;
    END LOOP;
    FOREACH t IN ARRAY ARRAY['crm.tenant_key', 'crm.integration_credential', 'crm.traveler'] LOOP
        FOREACH p IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE'] LOOP
            IF NOT pg_catalog.has_table_privilege('crm_app', t, p) THEN
                RAISE EXCEPTION 'crm-003: crm_app lacks % on % (default privileges FOR ROLE crm_owner)', p, t;
            END IF;
        END LOOP;
    END LOOP;
    IF pg_catalog.has_table_privilege('crm_app', 'crm.tenant_key', 'TRUNCATE') THEN
        RAISE EXCEPTION 'crm-003: crm_app may TRUNCATE crm.tenant_key';
    END IF;
    IF NOT (pg_catalog.has_table_privilege('crm_app', 'crm.audit_event', 'INSERT')
            AND pg_catalog.has_table_privilege('crm_app', 'crm.audit_event', 'SELECT')) THEN
        RAISE EXCEPTION 'crm-003: crm_app must INSERT and SELECT crm.audit_event';
    END IF;
    FOREACH p IN ARRAY ARRAY['UPDATE', 'DELETE', 'TRUNCATE'] LOOP
        IF pg_catalog.has_table_privilege('crm_app', 'crm.audit_event', p) THEN
            RAISE EXCEPTION 'crm-003: crm_app may % crm.audit_event (append-only)', p;
        END IF;
    END LOOP;
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_policy pol JOIN pg_catalog.pg_class c ON c.oid = pol.polrelid
               WHERE c.relnamespace = 'crm'::regnamespace AND 0 = ANY (pol.polroles)) THEN
        RAISE EXCEPTION 'crm-003: a crm policy applies TO PUBLIC (catalogue rule b); name the CRM roles';
    END IF;
    IF pg_catalog.has_function_privilege('public', 'crm.reject_append_only_change()', 'EXECUTE')
       OR pg_catalog.has_function_privilege('public', 'crm.tenant_key_guard()', 'EXECUTE') THEN
        RAISE EXCEPTION 'crm-003: a crm trigger function is executable by PUBLIC (SEC-4)';
    END IF;
END $$;

